"use client";
import { useState } from "react";
export default function SettingsPage(){const [theme,setTheme]=useState("dark");return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-4xl"><h1 className="text-2xl font-semibold">Settings</h1><div className="mt-6 space-y-5"><section className="rounded-2xl border border-white/10 bg-[#151515] p-5"><h2 className="font-semibold">Appearance</h2><div className="mt-4 flex gap-2">{["dark","light"].map(x=><button key={x} onClick={()=>setTheme(x)} className={`rounded-lg px-5 py-2 text-sm capitalize ${theme===x?"bg-orange-500 font-semibold text-black":"bg-white/5 text-white/50"}`}>{x}</button>)}</div></section>{[["Account","Profile editing and PIN setup — Coming Soon"],["Notifications","Notification preferences — Coming Soon"],["Devices","Managing logged-in devices — Coming Soon"]].map(([title,text])=><section key={title} className="rounded-2xl border border-white/10 bg-[#151515] p-5"><h2 className="font-semibold">{title}</h2><p className="mt-2 text-sm text-white/40">{text}</p></section>)}</div></div></main>}
